 1	/**
 2	 * Sorts integer arrays in ascending order using merge sort.
 3	 */
 4	public final class MergeSort {
 5	
 6	    private MergeSort() {
 7	    }
 8	
 9	    /**
10	     * Sorts the provided array in place. Null and single-element arrays are left unchanged.
11	     */
12	    public static void sort(int[] values) {
13	        if (values == null || values.length < 2) {
14	            return;
15	        }
16	
17	        int[] buffer = new int[values.length];
18	        mergeSort(values, buffer, 0, values.length);
19	    }
20	
21	    private static void mergeSort(int[] values, int[] buffer, int start, int end) {
22	        if (end - start < 2) {
23	            return;
24	        }
25	
26	        int middle = start + (end - start) / 2;
27	
28	        mergeSort(values, buffer, start, middle);
29	        mergeSort(values, buffer, middle, end);
30	
31	        if (isOrderedAcrossBoundary(values, middle)) {
32	            return;
33	        }
34	
35	        merge(values, buffer, start, middle, end);
36	    }
37	
38	    private static boolean isOrderedAcrossBoundary(int[] values, int middle) {
39	        return values[middle - 1] <= values[middle];
40	    }
41	
42	    private static void merge(int[] values, int[] buffer, int start, int middle, int end) {
43	        System.arraycopy(values, start, buffer, start, end - start);
44	
45	        int leftIndex = start;
46	        int rightIndex = middle;
47	        int mergedIndex = start;
48	
49	        while (leftIndex < middle && rightIndex < end) {
50	            if (buffer[leftIndex] <= buffer[rightIndex]) {
51	                values[mergedIndex++] = buffer[leftIndex++];
52	            } else {
53	                values[mergedIndex++] = buffer[rightIndex++];
54	            }
55	        }
56	
57	        while (leftIndex < middle) {
58	            values[mergedIndex++] = buffer[leftIndex++];
59	        }
60	    }
61	
62	    public static void main(String[] args) {
63	        int[] values = {38, 27, 43, 10};
64	
65	        sort(values);
66	        printValues(values);
67	    }
68	
69	    private static void printValues(int[] values) {
70	        System.out.println(formatValues(values));
71	    }
72	
73	    private static String formatValues(int[] values) {
74	        if (values.length == 0) {
75	            return "";
76	        }
77	
78	        StringBuilder result = new StringBuilder();
79	        result.append(values[0]);
80	
81	        for (int i = 1; i < values.length; i++) {
82	            result.append(' ').append(values[i]);
83	        }
84	
85	        return result.toString();
86	    }
87	}

